function App() {
  const [role, setRole] = useState('user');
  const can = (action) => action === 'delete' ? role === 'admin' : true;
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>Role-gated UI (UX only)</h3>
      <label>Role: 
        <select value={role} onChange={e => setRole(e.target.value)}>
          <option value="user">user</option>
          <option value="admin">admin</option>
        </select>
      </label>
      <p>Viewing as <b>{role}</b></p>
      <button>View</button>{' '}
      {can('delete') && <button>Delete (admin)</button>}
      <p style={{ fontSize: 12, color: '#666' }}>The server must still re-check 'delete' — hiding the button is not security.</p>
    </div>
  );
}

